// Generated by scripts/build_offline_cache.py. Documents stay in IndexedDB.
const CACHE = 'flowrite-__CACHE_VERSION__';
const FILES = __PRECACHE_FILES__;
const ROOT = new URL('./', self.location.href);
const assetURL = path => new URL(path.split('/').map(encodeURIComponent).join('/'), ROOT).href;
const ASSETS = new Set(FILES.map(assetURL));

self.addEventListener('install', event => {
  // Installation is atomic: don't activate an incomplete offline build.
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(
    FILES.map(path => new Request(assetURL(path), {cache: 'reload'}))
  )));
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('flowrite-') && key !== CACHE || key === 'flutter-app-cache' ||
          key === 'flutter-temp-cache' || key === 'flutter-app-manifest') await caches.delete(key);
    }
    await self.clients.claim();
  })());
});
self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  // Never cache credentials, document requests, or third-party API responses.
  if (request.method !== 'GET' || url.origin !== ROOT.origin ||
      !url.pathname.startsWith(ROOT.pathname) || (url.pathname === ROOT.pathname + 'dav' || url.pathname.startsWith(ROOT.pathname + 'dav/'))) return;
  if (request.mode === 'navigate') {
    event.respondWith(caches.open(CACHE).then(cache => cache.match(new URL('index.html', ROOT)))
      .then(cached => cached || fetch(request)));
  } else {
    const canonical = new URL(url);
    canonical.pathname = url.pathname.split('/').map(part => encodeURIComponent(decodeURIComponent(part))).join('/');
    canonical.search = '';
    if (!ASSETS.has(canonical.href)) return;
    event.respondWith(caches.open(CACHE).then(cache => cache.match(canonical.href))
      .then(cached => cached || fetch(request)));
  }
});
